    req.on('error', reject);
  });
}

function isJsonContentType(ct: string | undefined): boolean {
  if (!ct) return false;
  const type = ct.split(';')[0]!.trim().toLowerCase();
  return type === 'application/json' || /^application\/[a-z0-9.+-]+\+json$/.test(type);
}

function validateInt(v: unknown, field: string, min: number, max: number, errors: FieldError[]): number | undefined {
  if (typeof v !== 'number' || !Number.isFinite(v)) {
    errors.push({ field, message: `${field} must be an integer from ${min} to ${max}` });
    return undefined;
  }
  if (!Number.isInteger(v) || v < min || v > max) {
    errors.push({ field, message: `${field} must be an integer from ${min} to ${max}` });
    return undefined;
  }
  return v;
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const errors: FieldError[] = [];
  const rawKey = req.headers['idempotency-key'];
  let key: string | undefined;
