        if (!Object.hasOwn(obj, 'input')) {
          errors.push({ field: 'input', message: 'input is required' });
        } else if (typeof obj.input !== 'string') {
          errors.push({ field: 'input', message: 'input must be a string' });
        } else if (obj.input.length < 1 || obj.input.length > 1000) {
          errors.push({ field: 'input', message: 'input must be 1 to 1000 characters' });
        } else if (obj.input.trim().length === 0) {
          errors.push({ field: 'input', message: 'input must not be only whitespace' });
