        if (Object.hasOwn(obj, 'failAttempts')) failAttempts = validateInt(obj.failAttempts, 'failAttempts', 0, 5, errors);
      }
    }
  }

  if (errors.length > 0 || input === undefined || steps === undefined || failAttempts === undefined) {
    return sendError(res, 400, 'invalid_request', 'The request is invalid.', errors);
  }

  const payload = JSON.stringify({ input, steps, failAttempts });
  db.exec('BEGIN IMMEDIATE');
  try {
    if (key !== undefined) {
      const existing = getByKeyStmt.get(key) as (JobRow & { payload: string }) | undefined;
      if (existing) {
        db.exec('COMMIT');
        if (existing.payload === payload) return send(res, 200, toJob(existing));
        return sendError(res, 409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload.');
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    insertStmt.run(id, input, steps, failAttempts, key ?? null, payload, now, now);
    db.exec('COMMIT');
    send(res, 201, toJob(getJobStmt.get(id) as unknown as JobRow));
  } catch (e) {
    try { db.exec('ROLLBACK'); } catch { /* ignore */ }
    throw e;
  }
}

function methodNotAllowed(res: ServerResponse, allow: string): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed.', undefined, { allow });
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  let pathname: string;
  try {
    pathname = new URL(req.url ?? '/', 'http://localhost').pathname;
  } catch {
    return sendError(res, 404, 'not_found', 'Not found.');
  }
  const method = req.method ?? 'GET';

  if (pathname === '/' || pathname === '/index.html') {
    if (method !== 'GET' && method !== 'HEAD') return methodNotAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' });
    res.end(method === 'HEAD' ? undefined : uiHtml);
    return;
  }
  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    const hb = heartbeatStmt.get() as { ts: number } | undefined;
    const up = !!hb && Date.now() - hb.ts < HEARTBEAT_FRESH_MS;
    return send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') {
      const rows = listStmt.all() as unknown as JobRow[];
      return send(res, 200, { jobs: rows.map(toJob) });
    }
    if (method === 'POST') return createJob(req, res);
    return methodNotAllowed(res, 'GET, POST');
  }
  const m = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (m) {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    let id: string;
    try {
      id = decodeURIComponent(m[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'Job not found.');
    }
    const row = getJobStmt.get(id) as unknown as JobRow | undefined;
    if (!row) return sendError(res, 404, 'not_found', 'Job not found.');
    return send(res, 200, toJob(row));
  }
  sendError(res, 404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT || 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((err) => {
    console.error(err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});
server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    try { db.close(); } catch { /* ignore */ }
    process.exit(0);
  });
  server.closeAllConnections();
  setTimeout(() => process.exit(0), 3000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

